<?php require_once __DIR__.'/../../includes/bootstrap.php';$u=require_login();$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT * FROM vw_booking_summary WHERE id=? AND user_id=?');$s->execute([$id,$u['id']]);$b=$s->fetch();if(!$b||$b['status']!=='confirmed') exit('Change request is only available for confirmed bookings.');$venues=db()->query("SELECT * FROM venues WHERE status='available' ORDER BY name")->fetchAll();$pageTitle='Request booking change';$ns=db()->prepare('SELECT COUNT(*) FROM notifications WHERE user_id=? AND is_read=0');$ns->execute([$u['id']]);$userUnreadNotifications=(int)$ns->fetchColumn();require __DIR__.'/../../includes/header.php';?><section class="page-hero"><div class="container"><div class="eyebrow">Post-confirmation workflow</div><h1 class="page-title">Request a change.</h1><p>Confirmed bookings are locked. Management reviews requested changes before any schedule or venue update.</p></div></section><section class="section"><div class="container narrow panel"><form method="post" action="<?=url('user/bookings/change_save.php')?>"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="booking_id" value="<?=$id?>"><div class="field"><label>Reason</label><textarea name="reason" rows="5" required></textarea></div><div class="form-grid" style="margin-top:15px"><div class="field"><label>Proposed start</label><input type="datetime-local" name="start_at"></div><div class="field"><label>Proposed end</label><input type="datetime-local" name="end_at"></div><div class="field full"><label>Proposed venue</label><select name="venue_id"><option value="">Keep current venue</option><?php foreach($venues as $v):?><option value="<?=$v['id']?>"><?=e($v['name'])?></option><?php endforeach;?></select></div></div><button class="btn btn-gold" style="margin-top:20px">Submit change request</button></form></div></section><?php require __DIR__.'/../../includes/footer.php'; ?>
